export async function createScene(engine, canvas, BABYLON) {
  const link = document.createElement("link");
  link.href = "https://fonts.googleapis.com/css2?family=Modak&display=swap";
  link.rel = "stylesheet";
  document.head.appendChild(link);

  console.clear();
  const scene = new BABYLON.Scene(engine);
  scene.useRightHandedSystem = true;
  scene.clearColor = new BABYLON.Color4(0.62, 0.57, 0.46);

  var camera = new BABYLON.ArcRotateCamera("camera", BABYLON.Tools.ToRadians(90), BABYLON.Tools.ToRadians(65), 10, BABYLON.Vector3.Zero(), scene);
  camera.setTarget(new BABYLON.Vector3(0.07, 1.14, 0.06));
  camera.alpha = 1.571;
  camera.lowerAlphaLimit = 1;
  camera.upperAlphaLimit = 2;
  camera.beta = 1.473;
  camera.lowerBetaLimit = 1;
  camera.upperBetaLimit = Math.PI / 2;
  camera.radius = 2.5;
  camera.lowerRadiusLimit = 2;
  camera.upperRadiusLimit = 4;
  camera.inertia = 0.4;
  camera.wheelDeltaPercentage = 0.3;
  camera.panningSensibility = 0;
  camera.minZ = 0.01;
  camera.maxZ = 10000;
  camera.attachControl(canvas, true);

  var hemiLight = new BABYLON.HemisphericLight("light", new BABYLON.Vector3(0, 1, 0), scene);
  hemiLight.intensity = 0.3;

  var light = new BABYLON.DirectionalLight("dirLight", new BABYLON.Vector3(-1, -2, -1), scene);
  light.position = new BABYLON.Vector3(4, 8, 4);

  let rootMesh;

  let head;
  let bicepsL;
  let forearmL;
  let bicepsR;
  let forearmR;
  let tail, chest;

  let originalRotations;
  let initPasswordHeadQuaternion, initHeadQuaternion;
  let targets;

  let hidePassword = true;

  BABYLON.SceneLoader.ImportMeshAsync("", "https://raw.githubusercontent.com/UN1TOne/3DAsset/master/", "otter-san.glb").then((result) => {
    rootMesh = result.meshes[0];
    rootMesh.normalizeToUnitCube = true;

    bicepsL = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Biceps.L_013")[0];
    forearmL = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Forearm.L_014")[0];
    bicepsR = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Biceps.R_030")[0];
    forearmR = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Forearm.R_031")[0];
    head = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Head_047")[0];
    tail = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Bone.001_051")[0];
    chest = rootMesh.getChildTransformNodes(false, (tn) => tn.name === "Chest_011")[0];

    initHeadQuaternion = head.rotationQuaternion;

    initPasswordHeadQuaternion = new BABYLON.Quaternion(0.167, -0.115, 0.001, 0.979);

    originalRotations = [
      { node: bicepsL, target: new BABYLON.Quaternion(-0.007, -0.004, -0.537, 0.843) },
      { node: forearmL, target: new BABYLON.Quaternion(0.028, 0.005, -0.201, 0.978) },
      { node: bicepsR, target: new BABYLON.Quaternion(0.007, 0.004, 0.537, 0.843) },
      { node: forearmR, target: new BABYLON.Quaternion(-0.028, -0.005, 0.201, 0.978) },
    ];

    targets = [
      { node: bicepsL, target: new BABYLON.Quaternion(0.159, 0.104, 0.368, 0.909) },
      { node: forearmL, target: new BABYLON.Quaternion(0.172, -0.133, 0.605, 0.765) },
      { node: bicepsR, target: new BABYLON.Quaternion(0.046, -0.162, -0.359, 0.917) },
      { node: forearmR, target: new BABYLON.Quaternion(0.172, 0.162, -0.627, 0.741) },
    ];

    addGUI();

    smoothArmRotate(originalRotations, 400);

    const tail_fromQuat = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.Z, BABYLON.Tools.ToRadians(35));
    const tail_toQuat = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.Z, BABYLON.Tools.ToRadians(-28));

    const chest_fromQuat = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.Z, BABYLON.Tools.ToRadians(-1));
    const chest_toQuat = BABYLON.Quaternion.RotationAxis(BABYLON.Axis.Z, BABYLON.Tools.ToRadians(3));

    let time = 0;

    scene.onBeforeRenderObservable.add(() => {
      time += engine.getDeltaTime() * 0.002;
      const t = (Math.sin(time) + 1) / 2;
      tail.rotationQuaternion = BABYLON.Quaternion.Slerp(tail_fromQuat, tail_toQuat, t);
      chest.rotationQuaternion = BABYLON.Quaternion.Slerp(chest_fromQuat, chest_toQuat, t);
    });
  });

  function getHeadLookQuaternion(length) {
    const maxLength = 20;
    const clamped = Math.min(length, maxLength);

    const maxYaw = BABYLON.Tools.ToRadians(15);
    const yaw = BABYLON.Scalar.Lerp(-maxYaw, maxYaw, clamped / maxLength);

    const pitch = BABYLON.Tools.ToRadians(15);
    const roll = 0;

    const lookQuat = BABYLON.Quaternion.RotationYawPitchRoll(yaw, pitch, roll);

    return lookQuat.multiply(initHeadQuaternion);
  }

  function rotateHeadTo(targetQuat, duration = 200, onComplete) {
    const startQuat = head.rotationQuaternion.clone();
    const endQuat = targetQuat.clone();
    const startTime = performance.now();

    const observer = scene.onBeforeRenderObservable.add(() => {
      const t = Math.min((performance.now() - startTime) / duration, 1);
      head.rotationQuaternion = BABYLON.Quaternion.Slerp(startQuat, endQuat, t);
      if (t === 1) {
        scene.onBeforeRenderObservable.remove(observer);
        if (onComplete) onComplete();
      }
    });
  }

  function smoothArmRotate(nodes, duration = 500) {
    const startTime = performance.now();
    const initialRotations = nodes.map(({ node }) => node.rotationQuaternion.clone());
    const targets = nodes.map(({ target }) => target.clone());

    const observer = scene.onBeforeRenderObservable.add(() => {
      const now = performance.now();
      const t = Math.min((now - startTime) / duration, 1);

      nodes.forEach((entry, i) => {
        const { node } = entry;
        node.rotationQuaternion = BABYLON.Quaternion.Slerp(initialRotations[i], targets[i], t);
      });

      if (t === 1) {
        scene.onBeforeRenderObservable.remove(observer);
      }
    });
  }

  function addGUI() {
    const plane = BABYLON.MeshBuilder.CreatePlane("plane", { width: 0.75, height: 0.5 }, scene);
    plane.position = new BABYLON.Vector3(0, 0.9, 0.5);
    plane.rotation = new BABYLON.Vector3(0, 0, 0);
    // plane.showBoundingBox = true;

    const advancedTexture = BABYLON.GUI.AdvancedDynamicTexture.CreateForMesh(plane);
    advancedTexture.rootContainer.paddingLeft = "350px";
    advancedTexture.rootContainer.scaleX = 1.95;
    advancedTexture.rootContainer.scaleY = 2.4;

    const panel = new BABYLON.GUI.StackPanel();
    panel.width = "100%";
    panel.height = "150%";
    panel.adaptHeightToChildren = true;
    panel.verticalAlignment = BABYLON.GUI.Control.VERTICAL_ALIGNMENT_CENTER;
    advancedTexture.addControl(panel);

    const idText = new BABYLON.GUI.TextBlock();
    idText.text = " Username";
    idText.color = "white";
    idText.height = "80px";
    idText.width = "100%";
    idText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    idText.fontSize = 40;
    idText.outlineColor = "black";
    idText.outlineWidth = "5";
    idText.fontFamily = "Modak";
    panel.addControl(idText);

    const usernameInput = new BABYLON.GUI.InputText();
    usernameInput.width = "100%";
    usernameInput.height = "100px";
    usernameInput.placeholderText = "Username";
    usernameInput.color = "black";
    usernameInput.background = "white";
    usernameInput.fontSize = 48;
    usernameInput.focusedBackground = "#515c77";
    // usernameInput.fontFamily = "Modak";
    panel.addControl(usernameInput);

    usernameInput.onFocusObservable.add(() => {
      rotateHeadTo(initHeadQuaternion, 300);
    });

    let passwordText = "";

    const pwdText = new BABYLON.GUI.TextBlock();
    pwdText.text = " Password";
    pwdText.color = "white";
    pwdText.height = "80px";
    pwdText.width = "100%";
    pwdText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    pwdText.fontSize = 40;
    pwdText.outlineColor = "black";
    pwdText.outlineWidth = "5";
    pwdText.fontFamily = "Modak";

    panel.addControl(pwdText);

    let passwordInput = new BABYLON.GUI.InputPassword();
    passwordInput.width = "100%";
    passwordInput.height = "100px";
    passwordInput.placeholderText = "Password";
    passwordInput.color = "black";
    passwordInput.text = "";
    passwordInput.prompt = "Enter your password";
    passwordInput.fontSize = 48;
    passwordInput.maxLength = 15;
    passwordInput.background = "white";
    passwordInput.focusedBackground = "#515c77";
    passwordInput.onTextChangedObservable.add(() => {
      passwordText = passwordInput.text;
    });
    panel.addControl(passwordInput);

    let plainInput = new BABYLON.GUI.InputText();
    plainInput.width = "100%";
    plainInput.height = "100px";
    plainInput.color = "black";
    plainInput.background = "white";
    plainInput.placeholderText = "Password";
    plainInput.isVisible = false;
    plainInput.fontSize = 48;
    plainInput.maxLength = 15;
    plainInput.focusedBackground = "#515c77";
    // plainInput.fontFamily = "Modak";

    plainInput.onTextChangedObservable.add(() => {
      passwordText = plainInput.text;
    });
    panel.addControl(plainInput);

    const toggleCheckbox = new BABYLON.GUI.Checkbox();
    toggleCheckbox.width = "40px";
    toggleCheckbox.height = "40px";
    toggleCheckbox.isChecked = true;
    toggleCheckbox.color = "white";
    toggleCheckbox.background = "#515c77";

    toggleCheckbox.onIsCheckedChangedObservable.add((value) => {
      hidePassword = value;

      if (hidePassword) {
        passwordInput.text = passwordText;
        passwordInput.isVisible = true;
        plainInput.isVisible = false;

        smoothArmRotate(targets, 400);
        rotateHeadTo(initHeadQuaternion, 300);
      } else {
        plainInput.text = passwordText;
        plainInput.isVisible = true;
        passwordInput.isVisible = false;

        smoothArmRotate(originalRotations, 400);
        rotateHeadTo(initPasswordHeadQuaternion, 300, () => {
          onPasswordChanged();
        });
      }
    });

    const checkboxText = new BABYLON.GUI.TextBlock();
    checkboxText.text = " Show Password";
    checkboxText.color = "white";
    checkboxText.height = "80px";
    checkboxText.width = "100%";
    checkboxText.fontFamily = "Modak";
    checkboxText.textHorizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    checkboxText.fontSize = 30;
    checkboxText.outlineColor = "black";
    checkboxText.outlineWidth = "4";

    const checkboxPanel = new BABYLON.GUI.StackPanel();
    checkboxPanel.width = "100%";
    checkboxPanel.height = "80px";
    checkboxPanel.isVertical = false;
    checkboxPanel.paddingTop = "20px";
    checkboxPanel.horizontalAlignment = BABYLON.GUI.Control.HORIZONTAL_ALIGNMENT_LEFT;
    checkboxPanel.addControl(toggleCheckbox);
    checkboxPanel.addControl(checkboxText);

    passwordInput.onTextChangedObservable.add(() => {
      if (passwordInput.text.length > 15) {
        passwordInput.text = passwordInput.text.slice(0, 15);
      }
      passwordText = passwordInput.text;

      onPasswordChanged();
    });

    passwordInput.onTextChangedObservable.add(triggerParticles);
    plainInput.onTextChangedObservable.add(triggerParticles);

    plainInput.onTextChangedObservable.add(() => {
      if (plainInput.text.length > 15) {
        plainInput.text = plainInput.text.slice(0, 15);
      }
      onPasswordChanged();
    });

    panel.addControl(checkboxPanel);

    passwordInput.onFocusObservable.add(() => {
      if (!hidePassword) rotateHeadTo(initPasswordHeadQuaternion, 300);
      smoothArmRotate(targets, 400);
    });
    plainInput.onFocusObservable.add(() => {
      rotateHeadTo(initPasswordHeadQuaternion, 300);
    });

    passwordInput.onBlurObservable.add(() => {
      rotateHeadTo(initHeadQuaternion, 300);
    });
    plainInput.onBlurObservable.add(() => {
      rotateHeadTo(initHeadQuaternion, 300);
    });

    const onPasswordChanged = () => {
      passwordText = hidePassword ? passwordInput.text : plainInput.text;

      if (!hidePassword) {
        const length = passwordText.length;
        const targetQuat = getHeadLookQuaternion(length);
        rotateHeadTo(targetQuat, 200);
      }
    };

    const texture = new BABYLON.Texture("/images/textures/shell.png", scene);
    texture.hasAlpha = true;

    let particleSystem = new BABYLON.ParticleSystem("stars", 20, scene);
    particleSystem.particleTexture = texture;
    particleSystem.createPointEmitter(new BABYLON.Vector3(0.6, 1, 0), new BABYLON.Vector3(0, 1, 0));

    particleSystem.minEmitBox = new BABYLON.Vector3(-1, 0, 0);
    particleSystem.maxEmitBox = new BABYLON.Vector3(1, 0, 0);

    // particleSystem.color1 = new BABYLON.Color4(1, 0.82, 0);
    // particleSystem.color2 = new BABYLON.Color4(1, 0.6, 0);
    particleSystem.color1 = new BABYLON.Color4(1, 1, 1, 1);
    particleSystem.colorDead = new BABYLON.Color4(0.35, 0.93, 0.93, 0.83);

    particleSystem.minSize = 0.075;
    particleSystem.maxSize = 0.15;

    particleSystem.minLifeTime = 0.1;
    particleSystem.maxLifeTime = 0.4;

    particleSystem.emitRate = 50;

    // particleSystem.blendMode = BABYLON.ParticleSystem.BLENDMODE_ONEONE;
    particleSystem.blendMode = BABYLON.ParticleSystem.BLENDMODE_STANDARD;

    particleSystem.direction1 = new BABYLON.Vector3(-4, 5, 0);
    particleSystem.direction2 = new BABYLON.Vector3(-2, 5, 0);

    particleSystem.minAngularSpeed = 0;
    particleSystem.maxAngularSpeed = Math.PI / 2;

    particleSystem.minEmitPower = 0.75;
    particleSystem.maxEmitPower = 1;
    particleSystem.updateSpeed = 0.005;

    particleSystem.isLocal = true;

    function triggerParticles() {
      const length = passwordText.length;
      const clampedLength = Math.min(length, 15);

      const baseX = 0;
      const maxOffset = 0.3;
      const offsetX = BABYLON.Scalar.Lerp(-maxOffset, maxOffset, clampedLength / 30);

      particleSystem.emitter = new BABYLON.Vector3(baseX + offsetX, 1, 0.5);

      particleSystem.start();

      setTimeout(() => {
        particleSystem.stop();
      }, 300);
    }
  }

  return scene;
}
